// coze-plugin: 数据分析插件
// 入口函数
async function handler(event, context) {
  const { data, operation } = JSON.parse(event.body);

  switch (operation) {
    case 'summarize':
      return {
        statusCode: 200,
        body: JSON.stringify({
          summary: summarize(data),
          count: data.length,
          avg: data.reduce((a, b) => a + b, 0) / data.length
        })
      };

    case 'filter':
      const { field, value } = context.params;
      return {
        statusCode: 200,
        body: JSON.stringify({
          results: data.filter(item => item[field] === value)
        })
      };

    default:
      return {
        statusCode: 400,
        body: JSON.stringify({ error: 'Unknown operation' })
      };
  }
}

function summarize(data) {
  // 汇总逻辑
  return {
    min: Math.min(...data),
    max: Math.max(...data),
    mean: data.reduce((a, b) => a + b, 0) / data.length
  };
}

module.exports = { handler };

# coze-plugin: 文本处理插件
import json

def handler(event, context):
    body = json.loads(event['body'])
    text = body.get('text', '')
    operation = body.get('operation', '')

    if operation == 'extract_keywords':
        # 简单关键词提取
        words = text.split()
        keywords = [w for w in words if len(w) > 3]
        return {
            'statusCode': 200,
            'body': json.dumps({
                'keywords': keywords[:10],
                'count': len(keywords)
            })
        }

    elif operation == 'sentiment':
        # 简单情感分析
        positive_words = {'好', '棒', '喜欢', '满意', '优秀'}
        negative_words = {'差', '糟', '不满', '失望', '问题'}
        pos = sum(1 for w in text if w in positive_words)
        neg = sum(1 for w in text if w in negative_words)
        sentiment = 'positive' if pos > neg else 'negative' if neg > pos else 'neutral'
        return {
            'statusCode': 200,
            'body': json.dumps({
                'sentiment': sentiment,
                'confidence': abs(pos - neg) / max(pos + neg, 1)
            })
        }

    return {'statusCode': 400, 'body': json.dumps({'error': 'Unknown operation'})}

# Coze API接入
import requests

class CozeClient:
    def __init__(self, bot_id, api_token):
        self.bot_id = bot_id
        self.api_token = api_token
        self.base_url = "https://api.coze.cn/v1"  # 国内版
        # self.base_url = "https://api.coze.com/v1"  # 国际版

    def chat(self, user_message, conversation_id=None):
        headers = {
            "Authorization": f"Bearer {self.api_token}",
            "Content-Type": "application/json"
        }

        payload = {
            "bot_id": self.bot_id,
            "user": "user-001",
            "query": user_message,
            "stream": False
        }

        if conversation_id:
            payload["conversation_id"] = conversation_id

        response = requests.post(
            f"{self.base_url}/chat",
            headers=headers,
            json=payload
        )

        return response.json()

    def chat_stream(self, user_message, conversation_id=None):
        """流式输出"""
        headers = {
            "Authorization": f"Bearer {self.api_token}",
            "Content-Type": "application/json"
        }

        payload = {
            "bot_id": self.bot_id,
            "user": "user-001",
            "query": user_message,
            "stream": True
        }

        response = requests.post(
            f"{self.base_url}/chat",
            headers=headers,
            json=payload,
            stream=True
        )

        for line in response.iter_lines():
            if line:
                yield line.decode('utf-8')

# 使用示例
client = CozeClient(
    bot_id="your-bot-id",
    api_token="your-api-token"
)

result = client.chat("查询订单状态")
print(result)
